-- SMO catalog import generated from smo-supplies-list.pdf
-- Missing stock counts and prices are intentionally initialized to zero.
-- The retired HDMI category is mapped to Office Supplies to match the current application schema.
-- Names for codes 104-00023 and 104-00031 were restored from their catalog sequence because the PDF omitted their visible name text.
-- Product variants are consolidated into configurable_options so requestors choose
-- Brand, Color, Size, Style, etc. from one inventory item.
-- Safe to rerun: existing consolidated rows are updated by the unique item_name key.

USE `defaultdb`;

START TRANSACTION;

ON DUPLICATE KEY UPDATE updated_at = VALUES(updated_at);

ON DUPLICATE KEY UPDATE
  supply_category_id = VALUES(supply_category_id),
  brand = VALUES(brand),
  model_number = VALUES(model_number),
  category = VALUES(category),
  requisition_tier = VALUES(requisition_tier),
  specifications = VALUES(specifications),
  configurable_options = VALUES(configurable_options),
  unit = VALUES(unit),
  updated_at = NOW();

COMMIT;
